# Check for parallel imaging - field names vary by vendor
parallel_factor = None

if "ParallelAcquisitionTechnique" in value.columns:
    pat = value["ParallelAcquisitionTechnique"].dropna()
    if len(pat) > 0 and pat.iloc[0] in ["NONE", "None", ""]:
        raise ValidationWarning("Parallel imaging (GRAPPA/SENSE) with factor 2 is recommended.")

if "ParallelReductionFactorInPlane" in value.columns:
    prf = value["ParallelReductionFactorInPlane"].dropna()
    if len(prf) > 0:
        parallel_factor = prf.iloc[0]
        if parallel_factor != 2:
            raise ValidationWarning(f"Parallel imaging factor should be 2. Found {parallel_factor}")
